{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — maximize total profit (unit price minus raw material cost minus processing cost), or minimize total processing cost, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits (maximum number of units) for each product, or can the factory produce and sell unlimited quantities of each product?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand limits exist or if quantities are unlimited."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product, must the number of units that complete stage A equal the number that complete stage B (i.e., every unit that enters stage A must also go through stage B, with no work-in-progress or leftover units)?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy constraint regarding flow balance between stages A and B."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Should the production quantities of each product be whole numbers (integer units), or is it acceptable to treat them as continuous values?"
  ],
  "rationale": "The response asks a single clarification question regarding the variable type (integer vs. continuous) for production quantities."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the processing cost, should it be calculated as (machine hours used on each equipment type) multiplied by (that equipment's cost per machine hour), summed over all equipment types?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific calculation method."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the effective machine hours for each equipment type (A1: 6000, A2: 10000, B1: 4000, B2: 7000, B3: 4000) hard upper limits that cannot be exceeded, or are they targets that could be exceeded at an additional cost?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the machine hour constraints (hard limits vs. flexible targets)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any minimum production requirement for each product, or can the plan choose to produce zero units of any product?"
  ],
  "rationale": "The response asks a single clarification question regarding minimum production constraints, presenting two mutually exclusive options for the same policy decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For Product I, which can be processed on multiple equipment types at each stage, should the plan be free to split Product I's units across the available equipment types (e.g., some units on A1 and some on A2, some on B1 and some on B3), or must all units of a given product use a single equipment type per stage?"
  ],
  "rationale": "The response asks a single clarification question regarding the allocation policy for Product I across equipment types."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For Product II, which can use any A equipment but only B1 for stage B, should the plan be free to split Product II's units across A1 and A2 for stage A?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy decision on whether to allow splitting units across equipment."
}

